<template><section><header class="d-flex justify-content-between align-items-end mb-4"><div><h1 class="page-title mb-1">Ngân hàng câu hỏi</h1><p class="page-subtitle mb-0">Quản lý câu hỏi dùng trong video và bài kiểm tra.</p></div><button class="btn btn-brand" @click="createQuestion"><i class="bi bi-plus-lg"></i> Thêm câu hỏi</button></header><div class="app-card p-3 mb-3"><div class="row g-2"><div class="col-md-7"><input v-model="search" class="form-control" placeholder="Tìm nội dung câu hỏi..."></div><div class="col-md-3"><select v-model="type" class="form-select"><option value="">Tất cả loại</option><option>SINGLE_CHOICE</option><option>MULTIPLE_CHOICE</option><option>TRUE_FALSE</option></select></div><div class="col-md-2"><button class="btn btn-light w-100"><i class="bi bi-funnel"></i> Bộ lọc</button></div></div></div><div class="app-card p-2"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Câu hỏi</th><th>Loại</th><th>Độ khó</th><th>Điểm</th><th>Đã dùng</th><th class="text-end">Thao tác</th></tr></thead><tbody><tr v-for="q in filtered" :key="q.id"><td><strong>{{ q.text }}</strong><small class="d-block text-secondary">Nguyễn Văn Giảng • 10/08/2026</small></td><td><span class="badge badge-soft-primary">{{ q.type }}</span></td><td><span :class="['badge',q.difficulty==='Dễ'?'badge-soft-success':q.difficulty==='Khó'?'badge-soft-danger':'badge-soft-warning']">{{ q.difficulty }}</span></td><td>{{ q.score }}</td><td>{{ q.used }}</td><td class="text-end"><button class="btn btn-light btn-sm me-1"><i class="bi bi-pencil"></i></button><button class="btn btn-light btn-sm"><i class="bi bi-three-dots"></i></button></td></tr></tbody></table></div></div></section></template>
<script setup>import { computed,ref } from 'vue';const search=ref(''),type=ref(''),questions=ref([{id:1,text:'Vue.js là gì?',type:'SINGLE_CHOICE',difficulty:'Dễ',score:10,used:4},{id:2,text:'Composition API mang lại những lợi ích nào?',type:'MULTIPLE_CHOICE',difficulty:'Trung bình',score:15,used:3},{id:3,text:'Vue Router là thư viện chính thức của Vue.',type:'TRUE_FALSE',difficulty:'Dễ',score:5,used:8},{id:4,text:'Giải thích sự khác nhau giữa ref và reactive.',type:'SHORT_ANSWER',difficulty:'Khó',score:20,used:2},{id:5,text:'Lifecycle hook nào chạy sau khi DOM được mount?',type:'SINGLE_CHOICE',difficulty:'Trung bình',score:10,used:6}]);const filtered=computed(()=>questions.value.filter(q=>(!type.value||q.type===type.value)&&q.text.toLowerCase().includes(search.value.toLowerCase())));function createQuestion(){questions.value.unshift({id:Date.now(),text:'Câu hỏi mới chưa có nội dung',type:'SINGLE_CHOICE',difficulty:'Dễ',score:10,used:0})}</script>
